import { LitElement, html, nothing, unsafeCSS } from "lit";
import { property, state } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import { NysFormControlElement, associateControlRefs } from "@nysds/internals";
import "./nys-checkboxgroup";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-checkbox is used. Importing them here
// (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render.
// nys-icon renders the checked-state checkmark; nys-textinput renders the
// "other" free-text field.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
import "@nysds/nys-icon";
import "@nysds/nys-textinput";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-checkbox.scss?inline";

/**
 * A checkbox input for binary choices or multi-select lists. Can be used standalone or in a `nys-checkboxgroup`.
 * Form-associated with validation via ElementInternals.
 *
 * Use for binary decisions (agree/disagree) or selecting multiple options from a list.
 * For single selection from 2-6 options, use `nys-radiobutton`. For immediate state changes, use `nys-toggle`.
 *
 * @summary Checkbox for binary choices or multi-select options.
 * @element nys-checkbox
 *
 * @slot description - Custom HTML description content.
 *
 * @fires nys-change - Fired when checked state changes. Detail: `{id, checked, name, value}`.
 * @fires nys-focus - Fired when checkbox gains focus.
 * @fires nys-blur - Fired when checkbox loses focus.
 * @fires nys-other-input - Fired when "other" text input value changes. Detail: `{id, name, value}`.
 *
 * @example Single
 * ```html
 * <nys-checkbox label="I agree to the terms" name="terms"></nys-checkbox>
 * ```
 *
 * @example Preselected
 * ```html
 * <nys-checkbox label="I agree to the terms" name="terms" checked></nys-checkbox>
 * ```
 */

export class NysCheckbox extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  /** Whether checkbox is checked. */
  @property({ type: Boolean, reflect: true }) checked = false;

  /** Prevents interaction. */
  @property({ type: Boolean, reflect: true }) disabled = false;

  /** Marks as required. Validates that checkbox is checked. */
  @property({ type: Boolean, reflect: true }) required = false;

  /** Visible label text. Required for accessibility. */
  @property({ type: String }) label = "";

  /** Helper text below label. Use slot for custom HTML. */
  @property({ type: String }) description = "";

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Name for form submission. Use same name for grouped checkboxes. */
  @property({ type: String, reflect: true }) name = "";

  /** Value submitted when checked. */
  @property({ type: String }) value = "";

  /** Form `id` to associate with when checkbox is outside form element. */
  @property({ type: String, reflect: true }) form: string | null = null;

  /** Shows error message when true. */
  @property({ type: Boolean, reflect: true }) showError = false;

  /** Error message text. Shown only when `showError` is true. */
  @property({ type: String }) errorMessage = "";

  /** Internal: Set by parent checkboxgroup. Do not set manually. */
  @property({ type: Boolean }) groupExist = false;

  /** Renders as tile with larger clickable area. Apply to group for consistency. */
  @property({ type: Boolean, reflect: true }) tile = false;

  /** Tooltip text shown on hover/focus of info icon. */
  @property({ type: String }) tooltip = "";

  /**
   * Checkbox size: `sm` (24px) or `md` (32px, default).
   * @default "md"
   */
  @property({ type: String, reflect: true }) size: "sm" | "md" = "md";
  @property({ type: Boolean, reflect: true }) other = false;
  @property({ type: Boolean }) showOtherError = false;

  /**
   * Id of an element in the host's light-DOM tree to borrow the accessible name
   * from (e.g. a table column `<th>`). Enables labelling a checkbox that has no
   * visible label of its own.
   */
  @property({ type: String }) labelledby = "";

  /**
   * Suppress the internal visible `<nys-label>` (use with `labelledby` for
   * table cells).
   */
  @property({ type: Boolean }) hideLabel = false;

  private _mobileQuery = window.matchMedia("(max-width: 479px)");
  @state() private isMobile = this._mobileQuery.matches;

  private _hasUserInteracted = false; // need this flag for "eager mode"

  public async getInputElement(): Promise<HTMLInputElement | null> {
    await this.updateComplete; // Wait for the component to finish rendering
    return this.shadowRoot?.querySelector("input") || null;
  }

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */

  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this.addEventListener("invalid", this._handleInvalid);
    this.addEventListener("blur", this._handleBlur);
    this._mobileQuery.addEventListener("change", this._handleMobileQuery);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("invalid", this._handleInvalid);
    this.removeEventListener("blur", this._handleBlur);
    this._mobileQuery.removeEventListener("change", this._handleMobileQuery);
  }

  firstUpdated() {
    // This ensures our element always participates in the form
    this._setValue();
    this._manageRequire();
    this._manageLabelClick();
    if (this.labelledby) this._syncExternalLabel();
  }

  willUpdate(changed: Map<string, unknown>) {
    // Dropping an external label must happen BEFORE render. Clearing the control's
    // element references also removes its aria-labelledby content attribute, so the
    // clear has to precede the render that restores the internal IDREF — otherwise
    // it would delete the very attribute that render just wrote.
    if (changed.has("labelledby") && !this.labelledby) {
      const input = this.shadowRoot?.querySelector("input");
      if (input) associateControlRefs(input, "labelledby", []);
    }
  }

  updated(changed: Map<string, unknown>) {
    // Applying an external label must happen AFTER render, once the input exists.
    if (changed.has("labelledby") && this.labelledby) this._syncExternalLabel();
  }

  /**
   * Point the native <input> at a light-DOM element that IDREF attributes cannot
   * reach across the shadow boundary. associateControlRefs sets the control's own
   * ariaLabelledByElements (honored in Chromium) plus a string aria-label fallback
   * for engines that do not yet resolve element references.
   *
   * Only ever called with an external labelledby set: with no external target the
   * native input keeps the internal same-root aria-labelledby IDREF that render()
   * emits, and must not be touched.
   */
  private _syncExternalLabel() {
    const input = this.shadowRoot?.querySelector("input");
    if (!input) return;
    const target = (this.getRootNode() as Document | ShadowRoot).getElementById(
      this.labelledby,
    );
    associateControlRefs(input, "labelledby", [target]);
  }

  /**
   * Form Integration
   * --------------------------------------------------------------------------
   */

  private _setValue() {
    if (!this.groupExist) {
      this.setFormValue(this.checked ? this.value : null);
    }
  }

  private _manageRequire() {
    const input = this.shadowRoot?.querySelector("input");
    const message = this.errorMessage || "This field is required";
    if (!input) return;

    if (this.required && !this.checked) {
      this.setValidityFromState({ valueMissing: true }, message, input);
    } else {
      this.clearValidity();
    }
  }

  private _setValidityMessage(message: string = "") {
    const input = this.shadowRoot?.querySelector("input");
    if (!input) return;

    // Toggle the HTML <div> tag error message
    this.showError = !!message;
    // If user sets errorMessage, this will always override the native validation message
    if (this.errorMessage?.trim() && message !== "") {
      message = this.errorMessage;
    }

    if (message) {
      this.setValidityFromState({ customError: true }, message, input);
    } else {
      this.clearValidity();
    }
  }

  private _validate() {
    const input = this.shadowRoot?.querySelector("input");
    if (!input) return;

    // Get the native validation state
    const validity = input.validity;
    let message = "";

    if (validity.valueMissing) {
      message = "This field is required";
    }

    this._setValidityMessage(message);
  }

  // Called automatically when the parent form is reset
  public formResetCallback() {
    this.checked = false;

    this.setFormValue(null);

    const input = this.shadowRoot?.querySelector("input");
    if (input) {
      input.checked = false;
    }

    // Reset validation UI
    this.showError = false;
    this.errorMessage = "";
    this.clearValidity();

    // Re-render UI
    this.requestUpdate();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */

  // This helper function is called to perform the element's native validation.
  checkValidity(): boolean {
    // If the radiogroup is required but no radio is selected, return false.
    if (this.required && !this.checked) {
      return false;
    }

    // Otherwise, optionally check the native input's validity if available.
    const input = this.shadowRoot?.querySelector("input");
    return input ? input.checkValidity() : true;
  }

  private _handleInvalid(event: Event) {
    event.preventDefault();

    this.showError = true;
    this._validate(); // Make sure validation message appears

    const input = this.shadowRoot?.querySelector("input");
    if (input) {
      // Focus only if this is the first invalid element (top-down approach)
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        // Find the first element in the form that is invalid
        const firstInvalidElement = elements.find(
          (element) =>
            typeof element.checkValidity === "function" &&
            !element.checkValidity(),
        );
        if (firstInvalidElement === this) {
          input.focus();
        }
      } else {
        // If not part of a form, simply focus.
        input.focus();
      }
    }
  }

  private _manageLabelClick = () => {
    const main = this.shadowRoot?.querySelector(
      ".nys-checkbox__main-container",
    );
    const inputEl = this.shadowRoot?.querySelector("input");

    if (!main || !inputEl) return;

    main.addEventListener("click", (e) => {
      const target = e.target as HTMLElement;

      // Let native input behavior work. Avoid double toggling the checkbox.
      if (target.tagName.toLowerCase() === "input") return;

      if (!this.disabled) {
        inputEl.click();
        inputEl.focus();
      }
    });
  };

  get _hasDescription() {
    // This accounts for both description prop or slotted content. Used for styling text alignment.
    const slot = this.querySelector('[slot="description"]');
    return !!this.description || !!slot;
  }

  get _isStandalone() {
    return this.parentElement?.tagName.toLowerCase() !== "nys-checkboxgroup";
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  private _handleMobileQuery = () => {
    this.isMobile = this._mobileQuery.matches;
  };

  private _emitChangeEvent() {
    this.dispatchEvent(
      new CustomEvent("nys-change", {
        detail: {
          id: this.id,
          checked: this.checked,
          name: this.name,
          value: this.value,
        },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private _emitOtherInputEvent() {
    this.dispatchEvent(
      new CustomEvent("nys-other-input", {
        detail: {
          id: this.id,
          name: this.name,
          value: this.value,
        },
        bubbles: true,
        composed: true,
      }),
    );
  }

  // Handle checkbox change event
  private async _handleChange(e: Event) {
    const { checked } = e.target as HTMLInputElement;
    const wasChecked = this.checked;

    this.checked = checked;

    if (!this.groupExist) {
      this.setFormValue(this.checked ? this.value : null);
    }

    // If unchecking "other", clear error state
    if (this.other && wasChecked && !checked) {
      this.showOtherError = false;
      this._hasUserInteracted = false;
      this._dispatchClearError();
    }

    this._validate();
    this._emitChangeEvent();
  }

  private _handleFocus() {
    this.dispatchEvent(new Event("nys-focus"));
  }

  private _handleBlur() {
    this.dispatchEvent(new Event("nys-blur"));

    if (this.other && this.checked) {
      this._hasUserInteracted = true;
      this._validateOtherAndEmitError();
    }
  }

  private _handleTextInputBlur() {
    this._hasUserInteracted = true;
    this._validateOtherAndEmitError();
  }

  private async _handleKeydown(e: KeyboardEvent) {
    if (e.code === "Space") {
      e.preventDefault();
      if (!this.disabled) {
        this.checked = !this.checked;
        this.setFormValue(this.checked ? this.value : null);

        // Wait for DOM updates before validating. This is necessary to ensure the native input validation state is updated before this.validate().
        await this.updateComplete;
        this._validate();

        this._emitChangeEvent();
      }
    }
  }

  private _handleTextInput(event: Event) {
    const input = event.target as HTMLInputElement;
    let newValue = input.value;
    this.value = newValue;

    if (this._hasUserInteracted) {
      this._validateOtherAndEmitError();
    }

    this._emitOtherInputEvent();
  }

  private _validateOtherAndEmitError() {
    if (!this.other) return;

    // Prevent early validation of the "other" input before the user interacts with it.
    // Additionally clear validation when "other" checkbox is unchecked
    if (!this.checked || !this._hasUserInteracted) {
      this.showOtherError = false;

      this._dispatchClearError();
      return;
    }

    const isInvalid = this.value.trim() === "";
    this.showOtherError = isInvalid;

    if (isInvalid) {
      this.dispatchEvent(
        new CustomEvent("nys-error", {
          detail: {
            id: this.id,
            name: this.name,
            type: "other",
            message: "Please enter a value for this option.",
            sourceCheckbox: this,
          },
          bubbles: true,
          composed: true,
        }),
      );
    } else {
      this._dispatchClearError();
    }
  }

  private _dispatchClearError() {
    this.dispatchEvent(
      new CustomEvent("nys-error-clear", {
        detail: { sourceCheckbox: this },
        bubbles: true,
        composed: true,
      }),
    );
  }

  render() {
    return html`
      <div class="nys-checkbox">
        <div
          class="nys-checkbox__main-container ${this._hasDescription
            ? "has-description"
            : ""}"
        >
          <div class="nys-checkbox__checkbox-wrapper">
            <input
              id=${this.id + "--native"}
              class="nys-checkbox__checkbox"
              type="checkbox"
              name="${ifDefined(this.name ? this.name : undefined)}"
              .checked=${this.checked}
              ?disabled=${this.disabled}
              .value=${this.value}
              ?required="${this.required}"
              form=${ifDefined(this.form || undefined)}
              aria-checked="${this.checked}"
              aria-disabled="${this.disabled ? "true" : "false"}"
              aria-required="${this.required}"
              aria-invalid=${this.showError ? "true" : "false"}
              aria-errormessage=${this.id + "--error"}
              aria-describedby=${ifDefined(
                this.showError ? this.id + "--error" : undefined,
              )}
              @change="${this._handleChange}"
              @focus="${this._handleFocus}"
              @keydown="${this._handleKeydown}"
              aria-labelledby=${ifDefined(
                !this.labelledby && (this.label || this.other)
                  ? this.id + "--label"
                  : undefined,
              )}
            />
            ${this.checked
              ? html`<nys-icon
                  name="check"
                  size="${this.size === "md"
                    ? "4xl"
                    : this.size === "sm"
                      ? "2xl"
                      : "4xl"}"
                  class="nys-checkbox__icon"
                ></nys-icon>`
              : ""}
          </div>
          ${this.hideLabel || this.labelledby || !(this.label || this.other)
            ? nothing
            : html`<nys-label
                id="${this.id}--label"
                tooltip=${this.tooltip}
                label="${this.label || (this.other ? "Other" : "")}"
                description=${ifDefined(this.description || undefined)}
                flag=${ifDefined(this.required ? "required" : undefined)}
                class=${this._isStandalone ? "standalone" : ""}
              >
                <slot name="description" slot="description"
                  >${this.description}</slot
                >
              </nys-label>`}
        </div>
        <div class="nys-checkbox__other-container">
          ${this.other && this.checked
            ? html`
                <nys-textinput
                  .value=${this.value}
                  id=${"radiobutton-other-" + this.id}
                  @nys-input=${this._handleTextInput}
                  @nys-blur=${this._handleTextInputBlur}
                  ariaLabel="Other"
                  aria-invalid=${this.showOtherError ? "true" : "false"}
                  width=${this.isMobile ? "full" : "md"}
                  ?disabled=${this.disabled}
                ></nys-textinput>
              `
            : ""}
        </div>
      </div>
      ${this.parentElement?.tagName.toLowerCase() !== "nys-checkboxgroup"
        ? html`<nys-errormessage
            id=${this.id + "--error"}
            class="single-error-message"
            ?showError=${this.showError}
            errorMessage=${this.internals?.validationMessage ||
            this.errorMessage}
            .showDivider=${!this.tile}
          ></nys-errormessage>`
        : ""}
    `;
  }
}

if (!customElements.get("nys-checkbox")) {
  customElements.define("nys-checkbox", NysCheckbox);
}
